    if path is None:
        path = []

    if start == goal:
        return path

    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == 1:
                next_cell = (i, j)
                if next_cell not in path:
                    path.append(next_cell)
                    if dfs(grid, next_cell, goal, path):
                        return path
                    else:
                        path.pop()

    return None

